// Trialsites country mapping -- shared by Build Harvest Requests and Select
// Candidates. build_workflow.py prepends this file, verbatim, to both nodes'
// sources, so the two can never disagree about which countries are harvested.
// It must never read another node or its own input: it is not a node of its own.
//
// "Only countries the CRO scraper already includes" (the operator's brief) is
// Section 12's clock table: every country the ICH GCP scraper takes has a row
// there, and Send can reach no other. Both lists are substituted at build time
// from NovaScout_MasterRef.md by n8n/sites/build_workflow.py.

const INCLUDED_COUNTRIES = ["Argentina", "Brazil", "Czech Republic", "Egypt", "Hungary", "India", "Mexico", "Pakistan", "Poland", "Romania", "South Africa", "Turkey", "UAE", "Albania", "Algeria", "Angola", "Armenia", "Australia", "Austria", "Azerbaijan", "Bahamas", "Bahrain", "Bangladesh", "Belgium", "Benin", "Bosnia and Herzegovina", "Bulgaria", "Burkina Faso", "Burundi", "Cambodia", "Cameroon", "Canada", "Chile", "China", "Colombia", "Congo", "Costa Rica", "Cote d'Ivoire", "Croatia", "Cyprus", "DR Congo", "Denmark", "Djibouti", "Dominican Republic", "Ecuador", "El Salvador", "Equatorial Guinea", "Estonia", "Ethiopia", "Finland", "France", "Gabon", "Gambia", "Georgia", "Germany", "Ghana", "Greece", "Guatemala", "Guinea", "Hong Kong", "Indonesia", "Ireland", "Israel", "Italy", "Jamaica", "Japan", "Jordan", "Kazakhstan", "Kenya", "Kosovo", "Kuwait", "Kyrgyzstan", "Latvia", "Lebanon", "Liberia", "Lithuania", "Luxembourg", "Macedonia", "Madagascar", "Malawi", "Malaysia", "Mali", "Malta", "Mauritania", "Mauritius", "Moldova", "Mongolia", "Montenegro", "Morocco", "Mozambique", "Nepal", "Netherlands", "New Zealand", "Nigeria", "Norway", "Oman", "Panama", "Papua New Guinea", "Paraguay", "Peru", "Philippines", "Portugal", "Qatar", "Rwanda", "Saint Lucia", "Saudi Arabia", "Senegal", "Serbia", "Singapore", "Slovakia", "Slovenia", "South Korea", "Spain", "Sri Lanka", "Suriname", "Sweden", "Switzerland", "Taiwan", "Tanzania", "Thailand", "Togo", "Trinidad and Tobago", "Tunisia", "Turkmenistan", "USA", "Uganda", "Ukraine", "United Kingdom", "Uruguay", "Uzbekistan", "Vietnam", "Zambia", "Zimbabwe"];
const CORE_COUNTRIES = ["Argentina", "Brazil", "Czech Republic", "Egypt", "Hungary", "India", "Mexico", "Pakistan", "Poland", "Romania", "South Africa", "Turkey", "UAE"];

// Trialsites spellings that are not the leads.country spelling, read from the
// live /countries list on 2026-10-09 (236 spellings). A spelling neither here
// nor equal to an included name is simply not harvested -- nothing guesses. The
// build refuses an alias whose target is not an included country, so a
// sanctioned jurisdiction can never be reached through this table ("Korea,
// Democratic People's Republic Of" is in Trialsites and deliberately absent).
const TRIALSITES_ALIASES = {
  'united states': 'USA',
  'united states of america': 'USA',
  'czechia': 'Czech Republic',
  'korea, south': 'South Korea',
  'korea, republic of': 'South Korea',
  'turkey (turkiye)': 'Turkey',
  'united arab emirates': 'UAE',
  'tanzania, united republic of': 'Tanzania',
  'democratic republic of the congo': 'DR Congo',
  'congo (the democratic republic of the)': 'DR Congo',
  'congo, democratic republic': 'DR Congo',
  'republic of the congo': 'Congo',
  'north macedonia': 'Macedonia',
  'the gambia': 'Gambia',
  'the bahamas': 'Bahamas',
  'bosnia & herzegovina': 'Bosnia and Herzegovina',
};

function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

// Accent-folded, lower-cased, curly apostrophes made straight: "Côte d’Ivoire"
// and "Türkiye" meet the table the way a person would expect.
function fold(v) {
  return str(v).normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[‘’]/g, "'")
    .toLowerCase().replace(/\s+/g, ' ');
}

const INCLUDED_BY_KEY = {};
INCLUDED_COUNTRIES.forEach(function (c) { INCLUDED_BY_KEY[fold(c)] = c; });
const CORE_KEYS = CORE_COUNTRIES.map(fold);

// leads.country for a Trialsites spelling, or null if it is not harvested.
function canonicalCountry(trialsitesName) {
  const k = fold(trialsitesName);
  if (Object.prototype.hasOwnProperty.call(INCLUDED_BY_KEY, k)) return INCLUDED_BY_KEY[k];
  if (Object.prototype.hasOwnProperty.call(TRIALSITES_ALIASES, k)) {
    const target = fold(TRIALSITES_ALIASES[k]);
    return Object.prototype.hasOwnProperty.call(INCLUDED_BY_KEY, target) ? INCLUDED_BY_KEY[target] : null;
  }
  return null;
}

function isCore(country) {
  return CORE_KEYS.indexOf(fold(country)) !== -1;
}

// Build Harvest Requests -- n8n Code node (Run Once for All Items).
//
// Workflow 1b, Trialsites. Input: the live /countries list (the HTTP node splits
// its JSON array into one item per country, {country, sites}). Output: one item
// per Trialsites country spelling that maps to an included country, per tier
// (A and B) -- each becomes one paginated /sites request. Core countries first,
// so if the run is cut short the countries worth the full geography weight are
// the ones already read.
//
// The country list is read live rather than written down because Trialsites
// spells some countries two ways ("Czech Republic" and "Czechia"; "United
// States" and "United States Of America") and a request for one spelling misses
// the rows filed under the other. A country with no sites at all costs no
// request.

const TIERS = ['A', 'B'];

// ---------------------------------------------------------------------------
// Node body
// ---------------------------------------------------------------------------

const rows = [];
$input.all().forEach(function (i) {
  const j = i.json || {};
  if (Array.isArray(j)) { j.forEach(function (r) { rows.push(r); }); return; }
  if (Array.isArray(j.countries)) { j.countries.forEach(function (r) { rows.push(r); }); return; }
  rows.push(j);
});

const seen = {};
const requests = [];
rows.forEach(function (r) {
  const name = str(r && r.country);
  if (!name || seen[name] || !(Number(r.sites) > 0)) return;
  seen[name] = true;
  const canonical = canonicalCountry(name);
  if (!canonical) return;
  TIERS.forEach(function (tier) {
    requests.push({ trialsites_country: name, country: canonical, tier: tier, core: isCore(canonical) });
  });
});
requests.sort(function (a, b) {
  return (a.core === b.core ? 0 : a.core ? -1 : 1) || a.country.localeCompare(b.country) ||
    a.trialsites_country.localeCompare(b.trialsites_country) || a.tier.localeCompare(b.tier);
});

if (!requests.length) {
  // The list came back empty or unreadable. Throwing fails the execution
  // loudly instead of logging a harvest that read nothing: a harvest log row
  // would otherwise stop the next attempt for a week.
  throw new Error('Trialsites /countries returned no harvestable country (' + rows.length + ' rows read)');
}
return requests.map(function (r) { return { json: r }; });

// Trialsites country mapping -- shared by Build Harvest Requests and Select
